  "quiz": [
    {
      "id": "q1",
      "q": "电影《夜航船》当年的导演是谁？",
      "options": [
        {
          "key": "A",
          "text": "甄世昌"
        },
        {
          "key": "B",
          "text": "林子安"
        },
        {
          "key": "C",
          "text": "何映明"
        },
        {
          "key": "D",
          "text": "刘丹青"
        }
      ],
      "answer": "B",
      "clue": "zc_liu_2",
      "explain": "画室里那张手绘的原版海报，片名下一行小字写着：导演林子安，主演戚婉如，监制甄世昌。"
    },
    {
      "id": "q2",
      "q": "当年银星摄影场那场火灾，对外上报的起火原因是什么？",
      "options": [
        {
          "key": "A",
          "text": "炮弹击中"
        },
        {
          "key": "B",
          "text": "锅炉爆炸"
        },
        {
          "key": "C",
          "text": "电线走火"
        },
        {
          "key": "D",
          "text": "有人纵火"
        }
      ],
      "answer": "C",
      "clue": "zc_office_3",
      "explain": "经理室抽屉夹层里的火灾报告副本，起火原因一栏写的是电线走火，页脚附注还记着后门铁链一副。"
    },
    {
      "id": "q3",
      "q": "票房的吴小囡与当年的导演林子安是什么关系？",
      "options": [
        {
          "key": "A",
          "text": "师生"
        },
        {
          "key": "B",
          "text": "邻居"
        },
        {
          "key": "C",
          "text": "父女"
        },
        {
          "key": "D",
          "text": "远亲"
        }
      ],
      "answer": "C",
      "clue": "zc_wu_4",
      "explain": "吴小囡铁盒底下那张旧照片，背面写着：囡囡四岁，子安摄，照片里的男人把小女孩举在肩上。"
    },
    {
      "id": "q4",
      "q": "戚婉如在一九三八年为什么告别了银幕？",
      "options": [
        {
          "key": "A",
          "text": "嗓子坏了"
        },
        {
          "key": "B",
          "text": "被一纸合同限制三年不得出演，并背着高额违约金"
        },
        {
          "key": "C",
          "text": "嫁到了香港"
        },
        {
          "key": "D",
          "text": "在拍戏时受了伤"
        }
      ],
      "answer": "B",
      "clue": "zc_qi_3",
      "explain": "戚婉如妆盒底层压着一九三八年的合同，条款规定三年内不得出演任何影片，违约金一万二千元，落款盖着甄世昌的印章。"
    },
    {
      "id": "q5",
      "q": "放映间铁皮柜最里层那几本没有标签的片子，来历是什么？",
      "options": [
        {
          "key": "A",
          "text": "买家寄来的样片"
        },
        {
          "key": "B",
          "text": "何映明偷偷翻拷的《夜航船》"
        },
        {
          "key": "C",
          "text": "戚婉如送来的旧片"
        },
        {
          "key": "D",
          "text": "甄世昌新拍的广告片"
        }
      ],
      "answer": "B",
      "clue": "zc_he_3",
      "explain": "最里层的片盒里叠着五本翻拷的片子，每本片头字幕卡写着夜航船和本数，盒边没有出库登记。"
    },
    {
      "id": "q6",
      "q": "刘丹青这几年在旧货摊上卖的是什么？",
      "options": [
        {
          "key": "A",
          "text": "旧海报原件"
        },
        {
          "key": "B",
          "text": "戏院的旧票根"
        },
        {
          "key": "C",
          "text": "放映机的零件"
        },
        {
          "key": "D",
          "text": "仿旧的手绘剧照卡"
        }
      ],
      "answer": "D",
      "clue": "zc_liu_3",
      "explain": "画室木箱里码着手绘的剧照卡，色调与旧卡一致，箱底垫着盖着银星大戏院章的空白底卡。"
    }
  ],
